// План specs/admin-plans.md, 1.1 (кейс AP-01). Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab, TARGET_EMAIL, TARGET_NAME } from './plans-helpers';
import { accountRows, loadedRowCount, searchBox } from './plans-read-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Plans tab shows all accounts with Plan, Source, Subscription status and Until columns #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);

    // Вкладки и заголовок
    for (const tab of ['Users', 'Plans', 'Funnel']) {
      await expect(page.getByRole('tab', { name: tab, exact: true })
        .or(page.getByRole('button', { name: tab, exact: true })).first()).toBeVisible();
    }
    await expect(page.getByRole('heading', { name: 'Plans' })).toBeVisible();

    // Поиск и фильтры с текущими значениями
    await expect(searchBox(page)).toBeVisible();
    // не проверено на сайте: подпись фильтра читается как текст combobox (кастомный) или выбранный option (<select>).
    for (const label of ['All plans', 'All sources', 'All statuses']) {
      await expect(page.getByRole('combobox').filter({ hasText: label })
        .or(page.getByRole('combobox', { name: label })).first()).toBeVisible();
    }

    // Колонки
    for (const header of ['Account', 'Plan', 'Source', 'Subscription status', 'Until']) {
      await expect(page.locator('th, [role="columnheader"]').filter({ hasText: new RegExp(`^${header}$`) }).first()).toBeVisible();
    }

    // Строки: больше одной, есть «בדיקה»
    expect(await loadedRowCount(page)).toBeGreaterThan(1);
    const target = accountRows(page).filter({ hasText: TARGET_EMAIL });
    await expect(target).toHaveCount(1);
    await expect(target).toContainText(TARGET_NAME);

    // В каждой строке — «Assign plan» или «Change / extend»
    const rows = accountRows(page);
    const n = await rows.count();
    for (let i = 0; i < n; i++) {
      await expect(rows.nth(i).getByRole('button', { name: /^(Assign plan|Change \/ extend)$/ }).first()).toBeVisible();
    }
  });
});
